def trial(g, ratio=1):
    flat=[x for row in g for x in row]
    bg=collections.Counter(flat).most_common(1)[0][0]
    out=[row[:] for row in g]
    cand=[]
    for i in range(len(g)):
      for j in range(i+1,len(g)):
        shared=0; miss=[]; bad=False
        for c,(a,b) in enumerate(zip(g[i],g[j])):
          if a!=bg and b!=bg:
            if a!=b: bad=True; break
            shared+=1
          elif (a==bg)!=(b==bg):
            miss.append((c,a,b))
        if not bad and shared>=2 and miss and len(miss)<=ratio*shared:
          cand.append((i,j,shared,len(miss)))
          for c,a,b in miss:
            if a==bg: out[i][c]=1
            if b==bg: out[j][c]=1
    return out,cand,bg
