def trial2(g, min_dist=4, min_shared=3, ratio=1):
    bg=collections.Counter(x for row in g for x in row).most_common(1)[0][0]
    cand=[]
    for i in range(len(g)):
      for j in range(i+min_dist,len(g)):
        shared=0; miss=[]; bad=False
        for c,(a,b) in enumerate(zip(g[i],g[j])):
          if a!=bg and b!=bg:
            if a!=b: bad=True; break
            shared+=1
          elif (a==bg)!=(b==bg): miss.append(c)
        if not bad and shared>=min_shared and miss and len(miss)<=ratio*shared:
          cand.append((i,j,shared,len(miss)))
    # group by distance; only distance with at least N matching row pairs considered strong
    counts=collections.Counter(j-i for i,j,_,_ in cand)
    strong={d for d,n in counts.items() if n>=2}
    out=[r[:] for r in g]
    for i,j,s,m in cand:
      if j-i in strong or (counts[j-i]==1 and s>=5 and m<=1):
        for c in range(len(g[0])):
          a,b=g[i][c],g[j][c]
          if a==bg and b!=bg: out[i][c]=1
          if b==bg and a!=bg: out[j][c]=1
    return out,cand,counts,strong
