        if best>=3: offsets.append(d)
    pairs=[]
    if offsets:
        for d in offsets:
            for i in range(h-d):
                good,sh,miss,bad=compare(g[i],g[i+d])
                if good and miss: pairs.append((i,i+d,miss))
    else:
        for i in range(h):
          for j in range(i+1,h):
            good,sh,miss,bad=compare(g[i],g[j])
            if good and miss and sh/(w or 1)>=.55:
                pairs.append((i,j,miss))
    out=[r[:] for r in g]
    for i,j,miss in pairs:
       for c in miss:
