program='''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(cell for row in grid for cell in row).most_common(1)[0][0]

    def compare(row_a, row_b):
        shared = 0
        missing = []
        for c, (a, b) in enumerate(zip(row_a, row_b)):
            if a != background and b != background:
                if a != b:
                    return False, 0, []
                shared += 1
            elif (a == background) != (b == background):
                missing.append(c)
        return shared >= 2 and len(missing) <= shared, shared, missing

    pairs = []
    repeated = False
    for distance in range(1, h):
        good = [compare(grid[r], grid[r + distance])[0] for r in range(h - distance)]
        start = None
        for r, is_good in enumerate(good + [False]):
            if is_good and start is None:
                start = r
            elif not is_good and start is not None:
                if r - start >= 3:
                    repeated = True
                    for k in range(start, r):
                        _, _, missing = compare(grid[k], grid[k + distance])
                        if missing:
                            pairs.append((k, k + distance, missing))
                start = None

    if not repeated:
        for i in range(h):
            for j in range(i + 1, h):
                good, shared, missing = compare(grid[i], grid[j])
                if good and missing and shared / w >= 0.55:
                    pairs.append((i, j, missing))

    result = [row[:] for row in grid]
    for i, j, columns in pairs:
        for c in columns:
            if grid[i][c] == background:
                result[i][c] = 1
            if grid[j][c] == background:
                result[j][c] = 1
    return result
